import {reproductionState} from './reproduction-core.mjs';
export function materialImportBlocker(p,mode,hasPlan){if(mode!=='runtime')return '材料只发送到你启动的本地工作台，托管预览不接收材料。';if(!p.paper?.blob||!p.paper.sha256)return '先在「论文与代码」导入本项目的 PDF。';if(p.repository?.kind!=='zip'||!p.repository.blob||!p.repository.sha256)return '代码需要原始 ZIP 文件；GitHub 目录项目可先导入对应提交的 ZIP。';if(!hasPlan)return '选择与本论文和代码对应的实验计划 JSON。';return '';}
export function bundleMatchesProject(bundle,p){return bundle?.project_id===p.id&&bundle?.expected?.paper===p.paper?.sha256&&bundle?.expected?.archive===p.repository?.sha256;}
export class MaterialIntake{
 constructor(parent){this.parent=parent;this.i=parent.i;this.planFile=null;this.planProject=null;this.busy=false;this.progress='';this.root='';}
 render(p){const s=reproductionState(p),e=x=>this.i.esc(x),hasPlan=this.planProject===p.id&&this.planFile,reason=materialImportBlocker(p,this.i.h.mode(),hasPlan),b=s.material_bundle,ready=b&&bundleMatchesProject(b,p)&&!s.bundle_stale;return `<section class="material-transfer"><div class="assessment-intro"><div><h3>将当前材料绑定到执行工作区</h3><p>服务器独立解析 PDF、检查 ZIP 内容并计算逐文件指纹。原始材料保存在你的本机，不发送到私有预览站点。</p></div><button class="btn text" data-intake="step" data-step="materials">查看论文与代码</button></div><div class="material-transfer-inputs"><div><p>论文：${e(p.paper?.name||'未导入')}<br>代码：${e(p.repository?.name||'未导入')}</p><label class="btn">选择实验计划 JSON<input class="sr-only" type="file" accept=".json,application/json" data-material-plan ${this.busy?'disabled':''}></label><p class="small-note">${hasPlan?e(this.planFile.name):'最大 2 MB。保留计划中的参考指纹；不会用上传文件覆盖不一致的参考值。'}</p></div><div><button class="btn" data-material-import ${reason||this.busy?'disabled':''}>${this.busy?'正在导入…':'导入 PDF、ZIP 与计划'}</button>${reason?`<p class="small-note">${e(reason)}</p>`:''}${this.progress?`<p role="status">${e(this.progress)}</p>`:''}</div></div>${b?`<div class="material-binding-receipt"><h4>实际导入回执</h4><p>论文 ${e(b.files?.paper?.sha256?.slice(0,16)||'未上传')} · ZIP ${e(b.files?.archive?.sha256?.slice(0,16)||'未上传')} · ${b.archive_files?.length||0} 个已提取文件</p>${!ready?'<p class="info-strip">当前材料或计划已变更，需要重新导入。</p>':''}<div class="field"><label for="material-code-root">代码根目录（相对 ZIP 解包目录）</label><input id="material-code-root" data-material-root value="${e(s.material_code_root||b.suggested_root||'.')}" placeholder=". / 仓库顶层目录" ${this.busy||b.status==='bound'?'disabled':''}></div><button class="btn" data-material-bind ${!ready||!b.files?.plan||this.busy||this.i.h.mode()!=='runtime'?'disabled':''}>绑定材料并核验</button>${b.binding?`<p class="small-note">已记录原计划与绑定计划的不同指纹；仅重定位材料路径。<br>绑定计划：${e(b.plan_path)}</p>`:''}</div>`:''}</section>`;}
 async send(bundle,kind,blob){const response=await fetch('/api/materials/'+bundle.id+'/'+kind,{method:'POST',headers:{'X-ArtiCheck-Client':'workbench','Content-Type':'application/octet-stream'},body:blob});const result=await response.json();if(!response.ok)throw Error(result.error?.message||'材料传输失败');return result;}
 async import(p){const reason=materialImportBlocker(p,this.i.h.mode(),this.planProject===p.id&&this.planFile);if(reason)throw Error(reason);const s=reproductionState(p),file=this.planFile,pdf=p.paper.blob,zip=p.repository.blob;this.busy=true;s.audit=null;s.stale=true;s.bundle_stale=true;this.i.h.render();try{let bundle=await this.i.h.request('/api/materials',{project_id:p.id,paper_sha256:p.paper.sha256,archive_sha256:p.repository.sha256});for(const [kind,blob,label]of[['paper',pdf,'读取 PDF 正文'],['archive',zip,'解包代码与逐文件指纹核对'],['plan',file,'验证实验计划']]){this.progress=label;this.i.h.render();bundle=await this.send(bundle,kind,blob);s.material_bundle=bundle;await this.i.save(p);}if(!bundleMatchesProject(bundle,p)||this.planFile!==file)throw Error('导入期间项目材料发生变化，请重新导入');s.bundle_stale=false;s.material_code_root=bundle.suggested_root||'.';this.progress='材料已导入，请确认代码根目录并绑定。';}finally{this.busy=false;await this.i.save(p);this.i.h.render();}}
 async bind(p){const s=reproductionState(p);if(this.i.h.mode()!=='runtime'||s.bundle_stale||!bundleMatchesProject(s.material_bundle,p))throw Error('材料回执与当前项目不一致，请重新导入');this.busy=true;this.progress='绑定实际材料并重新核验';this.i.h.render();try{const bundle=await this.i.h.request('/api/materials/'+s.material_bundle.id+'/bind',{code_root:s.material_code_root||s.material_bundle.suggested_root||'.'});if(!bundleMatchesProject(bundle,p))throw Error('绑定期间项目材料发生变化');s.material_bundle=bundle;s.plan_path=bundle.plan_path;s.audit=await this.i.h.request('/api/reproduction/audit',{plan_path:s.plan_path,project_id:p.id,paper_sha256:p.paper.sha256,archive_sha256:p.repository.sha256,material_bundle_id:bundle.id});if(!bundleMatchesProject(bundle,p)){s.audit=null;s.stale=true;throw Error('项目材料已经变化，需要重新核验');}s.stale=false;this.progress='核验完成；矛盾与缺少的证据保留在下方。';}finally{this.busy=false;await this.i.save(p);this.i.h.render();}}
 bindEvents(){document.addEventListener('change',event=>{const input=event.target;if(!input.hasAttribute('data-material-plan')||!input.files?.[0])return;const p=this.i.current(),file=input.files[0];if(file.size>2_000_000){this.parent.error='实验计划最大 2 MB';this.i.h.render();return;}this.planFile=file;this.planProject=p.id;const s=reproductionState(p);s.audit=null;s.stale=true;s.bundle_stale=true;this.i.save(p);this.i.h.render();});document.addEventListener('input',event=>{if(event.target.hasAttribute('data-material-root')){reproductionState(this.i.current()).material_code_root=event.target.value;this.i.save();}});document.addEventListener('click',async event=>{const button=event.target.closest('[data-material-import],[data-material-bind]');if(!button)return;this.parent.error='';try{if(button.hasAttribute('data-material-import'))await this.import(this.i.current());else await this.bind(this.i.current());}catch(error){this.parent.error=error.message;this.i.h.render();}});}
}
